import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Publishing a Portal","description":"Publish a page as a Portal, share it, and restrict access.","frontmatter":{"title":"Publishing a Portal","description":"Publish a page as a Portal, share it, and restrict access."},"headers":[],"relativePath":"en/seiten/portal-veroeffentlichen.md","filePath":"en/seiten/portal-veroeffentlichen.md","lastUpdated":1787319236000}'),n={name:"en/seiten/portal-veroeffentlichen.md"};function s(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="publishing-a-portal" tabindex="-1">Publishing a Portal <a class="header-anchor" href="#publishing-a-portal" aria-label="Permalink to &quot;Publishing a Portal&quot;">​</a></h1><p>A page is initially only visible internally. Only a <strong>Portal link</strong> makes it reachable from outside.</p><h2 id="creating-a-portal-link" tabindex="-1">Creating a Portal link <a class="header-anchor" href="#creating-a-portal-link" aria-label="Permalink to &quot;Creating a Portal link&quot;">​</a></h2><ol><li>Open the page.</li><li>Choose <strong>Share this page</strong>.</li><li>Click <strong>Create portal link</strong>.</li></ol><p>After that, these become available:</p><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td><strong>Copy</strong></td><td>Copies the link to the clipboard</td></tr><tr><td><strong>Open</strong></td><td>Opens the Portal in a new tab</td></tr><tr><td><strong>Preview</strong></td><td>View as Smartphone or Desktop</td></tr><tr><td><strong>QR code</strong></td><td>Downloadable code</td></tr><tr><td><strong>Set restrictions</strong></td><td>Restrict access</td></tr><tr><td><strong>Add link</strong></td><td>Another, independent link</td></tr><tr><td><strong>Delete</strong></td><td>Remove the link</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">A Portal link is public by default</p><p>Without an additional restriction, <strong>anyone with the link</strong> can open the Portal. The link isn&#39;t guessable, but it&#39;s unprotected — if it gets forwarded, it keeps working there.</p><p>Decide who should have access via <em>Set restrictions</em> <strong>before</strong> distributing the link.</p></div><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p><strong>Preview</strong> shows the page as <strong>Smartphone</strong> or <strong>Desktop</strong>.</p><p>If you don&#39;t have a Portal link yet, ApptiveGrid asks:</p><blockquote><p><em>Viewing this preview as a Portal requires a published Portal link. Would you like to create one now?</em></p></blockquote><p><strong>Create and show preview</strong> creates it for you. <strong>Back to editing</strong> returns you to the editor.</p><div class="tip custom-block"><p class="custom-block-title">Always check both widths</p><p>Layouts that look right on desktop often break on smartphones — especially horizontal layouts with several evaluation blocks. The preview costs two clicks and saves you feedback from users.</p></div><h2 id="restricting-access" tabindex="-1">Restricting access <a class="header-anchor" href="#restricting-access" aria-label="Permalink to &quot;Restricting access&quot;">​</a></h2><p><strong>Set restrictions</strong> opens <em>Set access permissions</em> with the question <em>Decide who has access</em>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Everyone</strong></td><td><em>Anyone with the link can access it</em></td></tr><tr><td><strong>With credentials</strong></td><td><em>Access only with a username and password</em></td></tr></tbody></table><p>For the second option, you set a <strong>username</strong>/<strong>password</strong> pair. This has nothing to do with ApptiveGrid accounts — recipients don&#39;t need one.</p><div class="danger custom-block"><p class="custom-block-title">Credentials are only visible once</p><p>After saving, <em>Permissions updated</em> appears with the note:</p><blockquote><p><em>For security reasons, it&#39;s not possible to view the username and password later. However, you can reset them at any time.</em></p></blockquote><p>Write both down immediately. Otherwise you&#39;ll have to set new credentials and send them to all recipients again.</p></div><p>Note: Portals use a <strong>different restriction model</strong> than forms. The comparison is in <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a>.</p><h2 id="multiple-links-to-the-same-portal" tabindex="-1">Multiple links to the same Portal <a class="header-anchor" href="#multiple-links-to-the-same-portal" aria-label="Permalink to &quot;Multiple links to the same Portal&quot;">​</a></h2><p><strong>Add link</strong> creates further named links. Each can be restricted and removed individually.</p><div class="tip custom-block"><p class="custom-block-title">Keep access separate</p><p>One link per audience — one for customer A, one for customer B, one for the intranet. When a collaboration ends, remove just that link. All the others stay valid, and no one needs a new password.</p><p>How many additional links are possible depends on your plan.</p></div><p>All links in a Space are collected under <a href="/en/zusammenarbeit/externe-links">Overview of external links</a>.</p><h2 id="qr-code" tabindex="-1">QR code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR code&quot;">​</a></h2><p>The QR code leads directly to the Portal — for posters, stands, and printed material.</p><div class="warning custom-block"><p class="custom-block-title">Printed codes can&#39;t be recalled</p><p>If you delete the Portal or the link, a printed code leads nowhere. For printed material, use a dedicated, named link that you keep in place permanently.</p></div><h2 id="what-visitors-see" tabindex="-1">What visitors see <a class="header-anchor" href="#what-visitors-see" aria-label="Permalink to &quot;What visitors see&quot;">​</a></h2><p>The published Portal displays the page in the configured <strong>Page layout</strong> — <em>Centered page</em>, <em>Full width</em>, or <em>Card view</em>. The note <em>Applies to the Portal display</em> on that setting is meant literally: it looks different in the editor.</p><p>Editing controls only appear to the extent you&#39;ve enabled them. For embedded Grid views, that&#39;s controlled by the block settings <em>Entries read only</em> and <em>Don&#39;t open detail view</em>.</p><div class="tip custom-block"><p class="custom-block-title">Editing also still depends on the person&#39;s permissions</p><p>If <em>Entries read only</em> is off, that doesn&#39;t mean every visitor can edit. If the person is signed in to ApptiveGrid when opening the Portal link and has a role with edit rights on the underlying Grid, they can edit entries directly in the embedded view. Without being signed in, or without a matching role, it stays read-only — the server enforces that.</p></div><div class="warning custom-block"><p class="custom-block-title">Check with fresh eyes before publishing</p><p>Open the Portal link in a private browser window — that is, without being signed in. Only then do you see what outsiders actually see. It&#39;s common to discover that an embedded view shows more columns than intended, and a test done while signed in with your own account may show editing options that anonymous visitors don&#39;t actually have.</p></div><h2 id="removing-a-link" tabindex="-1">Removing a link <a class="header-anchor" href="#removing-a-link" aria-label="Permalink to &quot;Removing a link&quot;">​</a></h2><p>Via <strong>Delete</strong> in the share dialog or in the <a href="/en/zusammenarbeit/externe-links">links overview</a>.</p><p>A removed link stops working immediately — even for people who saved it. The page itself remains.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/seiten/portal-einbetten">Embedding a Portal</a></li><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li><li><a href="/en/zusammenarbeit/externe-links">Overview of external links</a></li></ul>',36)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
